export interface ToolCall {
  toolCallId: string;
  toolName: string;
  args: Record<string, unknown>;
  error?: unknown;
  result?: unknown;
  // Incremental output written by a long-running tool before it returns.
  progress?: unknown[];
}

export type Message = UserMessage | AgentMessage;

const USER_FROM = 'user';
export interface UserMessage {
  id: string;
  threadId: string;
  content: UserContent;
  from: typeof USER_FROM;
  /**
   * A system message: produced or handled by the host app rather than typed by the user or generated by
   * the agent (e.g. a slash command, or an automatic notice). Styled differently. It may still be sent to
   * the agent as a turn.
   */
  local?: boolean;
}

export interface TextPart {
  type: 'text';
  text: string;
}
export interface ImagePart {
  type: 'image';
  image: string;
}
export interface FilePart {
  type: 'file';
  data: string;
}
export type UserContent = Array<TextPart | ImagePart | FilePart>;

// Resolved types with metadata from file service
export interface ResolvedImagePart extends ImagePart {
  filename?: string;
  mediaType?: string;
}
export interface ResolvedFilePart extends FilePart {
  filename?: string;
  mediaType?: string;
}
export type ResolvedUserContent = Array<TextPart | ResolvedImagePart | ResolvedFilePart>;

export interface Attachment {
  urn: string;
  filename: string;
  type: 'file' | 'image';
  thumbnailUrl?: string;
}

export interface Reasoning {
  id: string;
  streaming: boolean;
  content: string;
}

export interface AgentError {
  type: 'error' | 'tripwire';
  message: string;
  details?: unknown;
}

const AGENT_FROM = 'agent';
export interface AgentMessage {
  id: string;
  threadId: string;
  content: string;
  from: typeof AGENT_FROM;
  streaming: boolean;
  toolCalls: ToolCall[];
  reasoning?: Reasoning;
  errors?: AgentError[];
  output?: unknown | null;
  /** A system message generated by the host app (e.g. a slash command reply) rather than by the agent. Styled differently. */
  local?: boolean;
  /** What the reply used, when the model provider reports it. */
  usage?: AgentUsage;
}

/** What one agent reply used, as agent-service reports it on the finished reply. */
export interface AgentUsage {
  /** Input tokens of the agent's last model call: how much of the context window the conversation takes up. */
  contextTokens: number;
  contextWindowTokens: number;
  /** Every token the reply used across its model calls, including calls made inside tools. */
  totalTokens: number;
  outputTokens: number;
  modelCalls: number;
}

/** Memory has started keeping the conversation short; normal behaviour that users should know about. */
export type ConversationNoticeReason = 'summarised' | 'older-messages-dropped';
/** The conversation is close to what the assistant can handle well. */
export type ConversationWarningReason = 'near-context-limit' | 'notes-condensed';

/**
 * How the conversation stands after the last reply: ok, a notice once memory starts summarising or dropping older
 * messages, or a warning once it is close to what the assistant can handle well.
 */
export type ConversationStatus = {
  contextTokens: number;
  contextWindowTokens: number;
} & (
  | { state: 'ok'; reason?: undefined }
  | { state: 'notice'; reason: ConversationNoticeReason; messageLimit?: number }
  | { state: 'warning'; reason: ConversationWarningReason }
);

/**
 * Agent context selection for routing user requests to specialized agents
 * Provides hints to the agent about which domain the user's question pertains to
 * Reserved field: 'agentContext' in the context Record
 */
export interface AgentContextSelection {
  context: string;
  subtopic: string;
  agent: string;
}
